/**
 * Table — composable table primitives for React PDF documents.
 *
 * @registryTitle PDF Table
 * @registryDescription Composable PDF table primitives with header, body, rows, cells, widths, and alignment.
 * @registryCategory data
 * @registryDemos basic=Basic, bordered=Bordered
 */

import * as React from "react";
import {
  Children,
  cloneElement,
  isValidElement,
  type ReactElement,
} from "react";
import { View, Text, StyleSheet } from "@react-pdf/renderer";
import type { Style } from "@react-pdf/types";
import {
  createPdfTextStyle,
  formatPdfValue,
  getPdfFlowProps,
  getPdfPrimitiveProps,
  mergePdfStyles,
  resolvePdfSize,
  type PdfFlowProps,
  type PdfPrimitiveProps,
  type PdfTextAlign,
  type PdfStyleInput,
  usePdfTheme,
} from "@/lib/pdf-theme";

export interface PdfTableProps extends PdfFlowProps {
  children: React.ReactNode;
  bordered?: boolean;
  striped?: boolean;
  noWrap?: boolean;
  style?: PdfStyleInput;
}

export interface PdfTableSectionProps extends PdfPrimitiveProps {
  children: React.ReactNode;
  style?: PdfStyleInput;
}

export interface PdfTableRowProps extends PdfFlowProps {
  children: React.ReactNode;
  header?: boolean;
  stripe?: boolean;
  bordered?: boolean;
  style?: PdfStyleInput;
}

export interface PdfTableCellProps extends PdfPrimitiveProps {
  children: React.ReactNode;
  width?: number | string;
  minWidth?: number | string;
  maxWidth?: number | string;
  align?: PdfTextAlign;
  header?: boolean;
  bordered?: boolean;
  style?: PdfStyleInput;
}

function isRowElement(
  child: React.ReactNode
): child is ReactElement<PdfTableRowProps> {
  return isValidElement(child) && child.type === PdfTableRow;
}

function isCellElement(
  child: React.ReactNode
): child is ReactElement<PdfTableCellProps> {
  return isValidElement(child) && child.type === PdfTableCell;
}

export function PdfTable({
  children,
  bordered = false,
  striped = false,
  noWrap = false,
  style,
  wrap,
  ...flowProps
}: PdfTableProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    table: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.md,
      borderWidth: bordered ? 1 : 0,
      overflow: "hidden",
      width: "100%",
    } as Style,
  });
  let rowIndex = 0;
  const processedChildren = Children.map(children, (child) => {
    if (!isValidElement(child)) return child;
    const section = child as ReactElement<PdfTableSectionProps>;
    return cloneElement(section, {
      children: Children.map(section.props.children, (rowChild) => {
        if (!isRowElement(rowChild)) return rowChild;
        const stripe =
          striped && !rowChild.props.header && rowIndex++ % 2 === 1;
        return cloneElement(rowChild, { bordered, stripe });
      }),
    });
  });
  return (
    <View
      {...getPdfFlowProps({ ...flowProps, wrap: wrap ?? !noWrap })}
      style={mergePdfStyles(styles.table, style)}
    >
      {processedChildren}
    </View>
  );
}

export function PdfTableHeader({
  children,
  style,
  minPresenceAhead = 60,
  ...primitiveProps
}: PdfTableSectionProps) {
  return (
    <View
      {...getPdfPrimitiveProps({ ...primitiveProps, minPresenceAhead })}
      style={mergePdfStyles(style)}
    >
      {children}
    </View>
  );
}

export function PdfTableBody({
  children,
  style,
  ...primitiveProps
}: PdfTableSectionProps) {
  return (
    <View {...getPdfPrimitiveProps(primitiveProps)} style={mergePdfStyles(style)}>
      {children}
    </View>
  );
}

export function PdfTableRow({
  children,
  header = false,
  stripe = false,
  bordered = false,
  style,
  wrap,
  ...flowProps
}: PdfTableRowProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    row: {
      backgroundColor: header
        ? theme.colors.muted
        : stripe
          ? "#f9fafb"
          : theme.colors.background,
      borderBottomColor: theme.colors.border,
      borderBottomWidth: bordered ? 1 : 0.75,
      flexDirection: "row",
      width: "100%",
    } as Style,
  });
  const processedChildren = Children.map(children, (child) => {
    if (!isCellElement(child)) return child;
    return cloneElement(child, { bordered, header });
  });
  return (
    <View
      {...getPdfFlowProps({ ...flowProps, wrap: wrap ?? false })}
      style={mergePdfStyles(styles.row, style)}
    >
      {processedChildren}
    </View>
  );
}

export function PdfTableCell({
  children,
  width,
  minWidth,
  maxWidth,
  align = "left",
  header = false,
  bordered = false,
  style,
  ...primitiveProps
}: PdfTableCellProps) {
  const theme = usePdfTheme();
  const resolvedWidth = resolvePdfSize(width);
  const content = formatPdfValue(children);
  const styles = StyleSheet.create({
    cell: {
      borderRightColor: theme.colors.border,
      borderRightWidth: bordered ? 1 : 0,
      flex: resolvedWidth ? undefined : 1,
      maxWidth: resolvePdfSize(maxWidth),
      minWidth: resolvePdfSize(minWidth),
      paddingHorizontal: 8,
      paddingVertical: header ? 7 : 8,
      width: resolvedWidth,
    } as Style,
    text: createPdfTextStyle(theme, {
      align,
      color: header ? theme.colors.foreground : theme.colors.mutedForeground,
      lineHeight: 1.35,
      size: "sm",
      weight: header ? "bold" : "normal",
    }),
  });
  return (
    <View
      {...getPdfPrimitiveProps(primitiveProps)}
      style={mergePdfStyles(styles.cell, style)}
    >
      {typeof content === "string" || typeof content === "number" ? (
        <Text style={styles.text}>{content}</Text>
      ) : (
        content
      )}
    </View>
  );
}

/**
 * PDF Theme — shared theme tokens and helpers for edbn/ui PDF components.
 *
 * @registryTitle PDF Theme
 * @registryDescription Theme provider, default tokens, and style helpers for PDF components.
 * @registryVariant pdf
 * @registryType registry:lib
 */

import * as React from "react";
import type {
  Bookmark,
  HitSlop,
  HyphenationCallback,
  Style,
} from "@react-pdf/types";

// ---- TYPES -----------------------------------------------------------------

export interface PdfTheme {
  colors: {
    background: string;
    foreground: string;
    mutedForeground: string;
    border: string;
    primary: string;
    primaryForeground: string;
    muted: string;
    destructive: string;
    warning: string;
    success: string;
  };
  spacing: {
    page: number;
    section: number;
    gap: number;
    sm: number;
    md: number;
    lg: number;
  };
  radii: {
    sm: number;
    md: number;
    lg: number;
  };
  typography: {
    fontFamily: string;
    monoFontFamily: string;
    xs: number;
    sm: number;
    base: number;
    lg: number;
    xl: number;
    xxl: number;
  };
}

export type PdfStyleInput = Style | PdfStyleInput[] | null | undefined | false;

export type PdfTextSize = "xs" | "sm" | "base" | "lg" | "xl" | "xxl";
export type PdfTextTone =
  | "default"
  | "muted"
  | "primary"
  | "destructive"
  | "warning"
  | "success";
export type PdfTextWeight = "normal" | "medium" | "bold";
export type PdfTextAlign = "left" | "center" | "right";
export type PdfBookmark = Bookmark;
export type PdfHitSlop = HitSlop;
export type PdfHyphenationCallback = HyphenationCallback;

export interface PdfTextStyleOptions {
  size?: PdfTextSize;
  tone?: PdfTextTone;
  weight?: PdfTextWeight;
  align?: PdfTextAlign;
  color?: string;
  fontFamily?: string;
  fontSize?: number;
  lineHeight?: number;
  marginBottom?: number;
}

export interface PdfPrimitiveProps {
  id?: string;
  bookmark?: PdfBookmark;
  debug?: boolean;
  fixed?: boolean;
  break?: boolean;
  minPresenceAhead?: number;
}

export interface PdfFlowProps extends PdfPrimitiveProps {
  wrap?: boolean;
}

export interface PdfTextRenderProps {
  pageNumber: number;
  totalPages: number;
  subPageNumber: number;
  subPageTotalPages: number;
}

export interface PdfViewRenderProps {
  pageNumber: number;
  subPageNumber: number;
}

export interface PdfAdvancedTextProps extends PdfFlowProps {
  render?: (props: PdfTextRenderProps) => React.ReactNode;
  hyphenationCallback?: PdfHyphenationCallback;
  orphans?: number;
  widows?: number;
}

export interface PdfAdvancedLinkProps extends PdfFlowProps {
  hitSlop?: PdfHitSlop;
}

// ---- DEFAULT THEME ---------------------------------------------------------

export const defaultPdfTheme: PdfTheme = {
  colors: {
    background: "#ffffff",
    foreground: "#111827",
    mutedForeground: "#6b7280",
    border: "#d1d5db",
    primary: "#2563eb",
    primaryForeground: "#ffffff",
    muted: "#f3f4f6",
    destructive: "#dc2626",
    warning: "#b45309",
    success: "#15803d",
  },
  spacing: {
    page: 36,
    section: 16,
    gap: 10,
    sm: 6,
    md: 10,
    lg: 16,
  },
  radii: {
    sm: 4,
    md: 7,
    lg: 10,
  },
  typography: {
    fontFamily: "Helvetica",
    monoFontFamily: "Courier",
    xs: 8,
    sm: 9,
    base: 10.5,
    lg: 13,
    xl: 18,
    xxl: 28,
  },
};

// ---- CONTEXT ---------------------------------------------------------------

const PdfThemeContext = React.createContext<PdfTheme>(defaultPdfTheme);

export interface PdfThemeProviderProps {
  theme?: Partial<PdfTheme>;
  children: React.ReactNode;
}

function mergeTheme(theme?: Partial<PdfTheme>): PdfTheme {
  if (!theme) return defaultPdfTheme;
  return {
    colors: { ...defaultPdfTheme.colors, ...theme.colors },
    spacing: { ...defaultPdfTheme.spacing, ...theme.spacing },
    radii: { ...defaultPdfTheme.radii, ...theme.radii },
    typography: { ...defaultPdfTheme.typography, ...theme.typography },
  };
}

export function PdfThemeProvider({ theme, children }: PdfThemeProviderProps) {
  const resolvedTheme = React.useMemo(() => mergeTheme(theme), [theme]);
  return (
    <PdfThemeContext.Provider value={resolvedTheme}>
      {children}
    </PdfThemeContext.Provider>
  );
}

export function usePdfTheme(): PdfTheme {
  return React.useContext(PdfThemeContext) ?? defaultPdfTheme;
}

// ---- STYLE HELPERS ---------------------------------------------------------

export function mergePdfStyles(...styles: PdfStyleInput[]): Style[] {
  return styles.flatMap((style): Style[] => {
    if (!style) return [];
    if (Array.isArray(style)) return mergePdfStyles(...style);
    return [style];
  });
}

export function getPdfPrimitiveProps({
  break: pageBreak,
  id,
  bookmark,
  debug,
  fixed,
  minPresenceAhead,
}: PdfPrimitiveProps = {}) {
  return {
    id,
    bookmark,
    debug,
    fixed,
    break: pageBreak,
    minPresenceAhead,
  };
}

export function getPdfFlowProps({
  wrap,
  ...primitiveProps
}: PdfFlowProps = {}) {
  return {
    ...getPdfPrimitiveProps(primitiveProps),
    wrap,
  };
}

export function getToneColor(theme: PdfTheme, tone?: string): string {
  switch (tone) {
    case "primary":
      return theme.colors.primary;
    case "muted":
      return theme.colors.mutedForeground;
    case "destructive":
      return theme.colors.destructive;
    case "warning":
      return theme.colors.warning;
    case "success":
      return theme.colors.success;
    default:
      return theme.colors.foreground;
  }
}

export function getPdfFontWeight(weight?: PdfTextWeight): 400 | 600 | 700 {
  if (weight === "bold") return 700;
  if (weight === "medium") return 600;
  return 400;
}

export function createPdfTextStyle(
  theme: PdfTheme,
  {
    size = "sm",
    tone = "default",
    weight = "normal",
    align = "left",
    color,
    fontFamily,
    fontSize,
    lineHeight = 1.45,
    marginBottom = 0,
  }: PdfTextStyleOptions = {}
): Style {
  return {
    color: color ?? getToneColor(theme, tone),
    fontFamily: fontFamily ?? theme.typography.fontFamily,
    fontSize: fontSize ?? theme.typography[size],
    fontWeight: getPdfFontWeight(weight),
    lineHeight,
    marginBottom,
    textAlign: align,
  } as Style;
}

export function isPdfNodeEmpty(value: React.ReactNode): boolean {
  if (value == null || typeof value === "boolean") return true;
  if (typeof value === "string") return value.trim().length === 0;
  if (Array.isArray(value)) return value.every(isPdfNodeEmpty);
  return false;
}

export function formatPdfValue(
  value: unknown,
  emptyValue: React.ReactNode = ""
): React.ReactNode {
  if (value == null) return emptyValue;
  if (React.isValidElement(value)) return value;
  if (Array.isArray(value)) {
    if (value.some(React.isValidElement)) {
      const nodes = value.filter(
        (item) => !isPdfNodeEmpty(item as React.ReactNode)
      );
      return nodes.length > 0 ? nodes : emptyValue;
    }
    const values = value
      .map((item) => formatPdfValue(item, ""))
      .filter((item) => !isPdfNodeEmpty(item as React.ReactNode));
    return values.length > 0 ? values.join(", ") : emptyValue;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? emptyValue
      : value.toISOString().slice(0, 10);
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? String(value) : emptyValue;
  }
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (typeof value === "string") {
    return value.trim().length > 0 ? value : emptyValue;
  }
  return emptyValue;
}

export function normalizePdfString(value: string | null | undefined): string {
  return value?.trim() ?? "";
}

export function clampPdfNumber(
  value: number | undefined,
  fallback: number,
  min = 0,
  max = Number.MAX_SAFE_INTEGER
): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.min(Math.max(value, min), max);
}

export function resolvePdfSize(
  value: number | string | undefined
): number | string | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) && value > 0 ? value : undefined;
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
  }
  return undefined;
}
